# Reproduce the original nearest-neighbor grid alignment using identifiers, not yields.
here<-dirname(normalizePath(sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)),winslash='/'));source(file.path(here,'common.R'));library(raster)
a<-args_named();out<-normal(need(a,'out'),FALSE);stopifnot(!dir.exists(out))
xy_path<-normal(need(a,'dsm-xy'));native_path<-normal(need(a,'native-grid'));ref_path<-normal(need(a,'reference-grid'));paired_path<-normal(need(a,'paired-cells'))
xy<-read.csv(xy_path);xy$profile_id<-paste0('Maize_',as.integer(xy$site));stopifnot(nrow(xy)==2030,!anyDuplicated(xy$profile_id))
native<-raster(native_path);ref<-raster(ref_path);stopifnot(compareCRS(native,ref),all(res(native)==12),all(res(ref)==12))
ix<-cellFromXY(native,xy[,c('x','y')]);stopifnot(!anyNA(ix),!anyDuplicated(ix))
values(native)<-NA;native[ix]<-seq_len(nrow(xy));aligned<-resample(native,ref,method='ngb')
p<-read.csv(paired_path);stopifnot(nrow(p)==1943,all(p$area_ha==.0144))
j<-extract(aligned,p[,c('x','y')]);stopifnot(!anyNA(j),all(j==as.integer(j)))
index<-data.frame(x=p$x,y=p$y,DHP=p$DHP,mukey=as.character(p$mukey),area_ha=p$area_ha,profile_id=xy$profile_id[j])
stopifnot(!anyDuplicated(paste(index$x,index$y)),!anyDuplicated(index$profile_id),length(unique(index$mukey))==6,all(index$DHP%in%c('SU','SH','BS','FS','TS')))
dir.create(out,recursive=TRUE);write.csv(index,file.path(out,'cell_index.csv'),row.names=FALSE)
writej(list(status='INDEX_READY_YIELD_JOIN_CHECK_PENDING',cells=1943,DSM_profiles=2030,mapunits=6,area_ha=sum(index$area_ha),method='Original native DSM grid to reference DHP grid by nearest neighbor; no cubic interpolation for statistics.',source_md5=as.list(setNames(unname(tools::md5sum(c(xy_path,native_path,ref_path,paired_path))),c('dsm_xy','native_grid','reference_grid','paired_cells'))),index_md5=md5(file.path(out,'cell_index.csv'))),file.path(out,'status.json'))
capture.output(sessionInfo(),file=file.path(out,'sessionInfo.txt'))
